get_stop_lev({89, 0}) ->
    #{lev => 89, break_times => 0, quest_id => 83400};
get_stop_lev({99, 0}) ->
    #{lev => 99, break_times => 0, quest_id => 83400};
get_stop_lev({99, 1}) ->
    #{lev => 99, break_times => 1, quest_id => 83410};
